  Object.freeze({ path: 'evidenceRefs', description: 'an array of non-empty strings if provided' }),
]);

function nonEmptyString(value) {
  return typeof value === 'string' && value.trim() !== '';
}

export function isAssessmentRequired(context = {}) {
  const role = context.role ?? context.assignment?.role;
  const operation = context.operation ?? context.assignment?.operation;
  return role === 'reviewer' || role === 'red-team' || (typeof operation === 'string' && operation.includes('recheck'));
}

export function assessmentRequirement(context = {}) {
  return isAssessmentRequired(context)
    ? Object.freeze({ required: true, path: 'assessment.verdict', allowed: ASSESSMENT_VERDICTS })
    : Object.freeze({ required: false, path: 'assessment.verdict', allowed: ASSESSMENT_VERDICTS });

export function roleUnit(unit, { role, kind = role, params = {}, findings = [] } = {}) {
  const task = params?.roleTasks?.[role] ?? params?.roleTasks?.[kind] ?? DEFAULT_ROLE_TASKS[kind];
  const hasFindings = Array.isArray(findings) && findings.length > 0;
  const stanceOptions = unit.stanceOptions ?? [];
  const hasStance = kind === 'panelist' && stanceOptions.length > 0;
  if (typeof task !== 'string' && !hasFindings && !hasStance) return unit;

  let objective = typeof task === 'string' ? wrap(task, unit.objective) : unit.objective;
  if (hasFindings) {
    objective += `\n\nThe previous round's checks reported these findings. Fix them and change nothing else:\n${findings.map((f) => `- ${f}`).join('\n')}`;
  }
  if (hasStance) {
    objective += `\n\nPassive stance measurement for this question. Declared choices: ${JSON.stringify(stanceOptions)}; \"other\" is also allowed.\nEnd your report by stating your stance and include \"stance\": {\"choice\": <one declared choice or \"other\">, \"confidence\": <number from 0 to 1>} in your agent-result.json claim. This optional measurement never changes whether your work passes.`;
  }
  return { ...unit, objective };

export function extractStance(agentClaim, options = []) {
  if (agentClaim?.stance === undefined) return { status: 'missing' };
  const stance = agentClaim.stance;
  if (!stance || typeof stance !== 'object' || Array.isArray(stance)) return { status: 'invalid', reason: 'stance-not-object' };
  if (typeof stance.choice !== 'string' || (!options.includes(stance.choice) && stance.choice !== 'other')) {
    return { status: 'invalid', reason: 'choice-not-declared' };
  }
  if (stance.confidence !== undefined && stance.confidence !== null
    && (typeof stance.confidence !== 'number' || !Number.isFinite(stance.confidence) || stance.confidence < 0 || stance.confidence > 1)) {
    return { status: 'invalid', reason: 'confidence-out-of-range' };
  }
  return { status: 'valid', choice: stance.choice, confidence: stance.confidence ?? null };
